// Source of truth: src/code/normalize-email.js
const email = $input.first().json;

const fromEmail =
  email.from?.emailAddress ||
  email.sender?.emailAddress ||
  {};

const senderName = fromEmail.name || 'Unknown Sender';
const senderEmail = fromEmail.address || null;
const subject = email.subject || '(No Subject)';
const htmlBody = email.body?.content || '';

function htmlToText(html) {
  if (!html) return '';
  return html
    .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, '')
    .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/li>/gi, '\n')
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

const cleanBody =
  htmlToText(htmlBody) ||
  email.bodyPreview ||
  '(Empty body)';

const messageId = email.id || null;
const conversationId = email.conversationId || null;
const webLink = email.webLink || null;

const warnings = [];
if (!senderEmail) warnings.push('senderEmail missing from Outlook payload');
if (!messageId) warnings.push('messageId missing — Outlook reply draft creation will fail');

return [{
  json: {
    messageId,
    conversationId,
    senderName,
    senderEmail: senderEmail || 'UNKNOWN',
    subject,
    cleanBody,
    htmlBody,
    webLink,
    _warnings: warnings.length ? warnings : undefined
  }
}];

